SET NAMES utf8mb4;
SET SESSION sql_mode='';
START TRANSACTION;

-- venda_caixas : 95 registros

-- item_venda_caixas : 139 registros

-- conta_recebers : 96 registros

-- estoque_movs : 139 registros

-- estoquemovpdvs : 139 registros

-- Contagens esperadas: venda_caixas=95, itens=139, contas=96, estoque_movs=139, estoquemovpdvs=139
SELECT
  (SELECT COUNT(*) FROM venda_caixas       WHERE id>=1000000) AS venda_caixas,
  (SELECT COUNT(*) FROM item_venda_caixas  WHERE id>=1000000) AS itens,
  (SELECT COUNT(*) FROM conta_recebers      WHERE id>=1000000) AS contas,
  (SELECT COUNT(*) FROM estoque_movs        WHERE id>=1000000) AS estoque_movs,
  (SELECT COUNT(*) FROM estoquemovpdvs      WHERE id>=1000000) AS estoquemovpdvs;

